#include <iostream>
#include <cmath>

int main() {
    int h, n;
    std::cin >> h >> n;
    n = n - 1 + (1 << h);
    int total = h;
    for (int index = 1; index <= h; ++index) {
        int current_bit = n & (1 << index);
        int prev_bit = n & (1 << (index - 1));
        if (!(((current_bit == 0) ? 1 : 0) ^ ((prev_bit == 0) ? 1 : 0))) {
            total += (1 << index) - 1;
        }
    }
    std::cout << total << std::endl;
    return 0;
}
